mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM member
    WHERE id = #{memberId}
        AND deleted_at IS NULL
)

SELECT EXISTS (
    SELECT 1
    FROM member
    WHERE login_id = #{loginId}
)

SELECT EXISTS (
    SELECT 1
    FROM member
    WHERE display_name = #{displayName}
)

SELECT EXISTS (
    SELECT 1
    FROM member
    WHERE display_name = #{displayName}
    AND id != #{memberId}
)

SELECT EXISTS (
    SELECT 1
    FROM member
    WHERE id = #{memberId}
        AND auth_version = #{authVersion}
        AND deleted_at IS NULL
)
